class RCPParser:
    def __init__(self, content: str):
        self.headers = {}
        self.body_elements = []
        self.parse(content)

    def parse(self, content: str):
        lines = content.splitlines()
        if not lines:
            raise ValueError('File is empty')

        if lines[0] != '%RCP/1.0':
            raise ValueError('Invalid magic line')

        header_ended = False
        header_lines_count = 0
        for i in range(1, len(lines)):
            line = lines[i]
            if line == '%%':
                header_ended = True
                header_lines_count = i
                break

            if '=' not in line:
                raise ValueError(f'Invalid header line: {line}')

            key, val = line.split('=', 1)
            if not re.match(r'^[a-z][a-z0-9_]*$', key):
                raise ValueError(f'Invalid header key: {key}')

            val = val.strip()
            if key in self.headers:
                raise ValueError(f'Duplicate header key: {key}')

            self.headers[key] = val

        if not header_ended:
            raise ValueError('Header block not terminated with %%')

        if 'id' not in self.headers or not self.headers['id']:
            raise ValueError('Missing or empty required header id')

        if 'title' not in self.headers or not self.headers['title']:
            raise ValueError('Missing or empty required header title')

        body_lines = lines[header_lines_count + 1:]

        current_block_type = None
        current_block_lines = []

        def flush_block():
            nonlocal current_block_type, current_block_lines
            if not current_block_type:
                return

            if current_block_type == 'N':
                items = []
                for b_line in current_block_lines:
                    items.append(b_line[3:])
                self.body_elements.append(('list_ordered', items))
            elif current_block_type == 'B':
                items = []
                for b_line in current_block_lines:
                    items.append(b_line[3:])
                self.body_elements.append(('list_unordered', items))
            elif current_block_type == '|':
                rows_cells = []
                for b_line in current_block_lines:
                    content_part = b_line[1:]
                    if content_part.endswith('|'):
                        content_part = content_part[:-1]
                    cells = [cell.strip() for cell in content_part.split('|')]
                    rows_cells.append(cells)

                num_cols = len(rows_cells[0])
                for row_idx, row in enumerate(rows_cells):
                    if len(row) != num_cols:
                        raise ValueError(f'Ragged table at row {row_idx}: expected {num_cols} columns, got {len(row)}')

                self.body_elements.append(('table', rows_cells))

            current_block_type = None
            current_block_lines = []

        for line in body_lines:
            if not line.strip():
                flush_block()
                continue

            if line.startswith(('S1> ', 'S2> ', 'S3> ', 'S4> ', 'S5> ', 'S6> ')):
                flush_block()
                level = int(line[1])
                text = line[4:]
                self.body_elements.append(('heading', (level, text)))
            elif line.startswith('P> '):
                flush_block()
                self.body_elements.append(('paragraph', line[3:]))
            elif line.startswith('A> '):
                flush_block()
                self.body_elements.append(('annotation', line[3:]))
            elif line.startswith('F> '):
                flush_block()
                rest = line[3:]
                if ' :: ' not in rest:
                    raise ValueError(f'Invalid figure line: {line}')
                ref, caption = rest.split(' :: ', 1)
                self.body_elements.append(('figure', (ref, caption)))
            elif line.startswith('N> '):
                if current_block_type != 'N':
                    flush_block()
                    current_block_type = 'N'
                current_block_lines.append(line)
            elif line.startswith('B> '):
                if current_block_type != 'B':
                    flush_block()
                    current_block_type = 'B'
                current_block_lines.append(line)
            elif line.startswith('|'):
                if current_block_type != '|':
                    flush_block()
                    current_block_type = '|'
                current_block_lines.append(line)
            else:
                raise ValueError(f'Unrecognized body line: {line}')

        flush_block()

