    def _convert(
        self, conv_input: _DocumentConversionInput, raises_on_error: bool
    ) -> Iterator[ConversionResult]:
        start_time = time.monotonic()

        for input_batch in chunkify(
            conv_input.docs(self.format_to_options),
            settings.perf.doc_batch_size,  # pass format_options
        ):
            _log.info("Going to convert document batch...")
            process_func = partial(
                self._process_document, raises_on_error=raises_on_error
            )

            if (
                settings.perf.doc_batch_concurrency > 1
                and settings.perf.doc_batch_size > 1
            ):
                with ThreadPoolExecutor(
                    max_workers=settings.perf.doc_batch_concurrency
                ) as pool:
                    for item in pool.map(
                        process_func,
                        input_batch,
                    ):
                        yield item
            else:
                for item in map(
                    process_func,
                    input_batch,
                ):
                    elapsed = time.monotonic() - start_time
                    start_time = time.monotonic()
                    _log.info(
                        f"Finished converting document {item.input.file.name} in {elapsed:.2f} sec."
                    )
                    yield item

    def _process_document(
        self, in_doc: InputDocument, raises_on_error: bool
    ) -> ConversionResult:
        valid = (
            self.allowed_formats is not None and in_doc.format in self.allowed_formats
        )
        if valid:
            conv_res = self._execute_pipeline(in_doc, raises_on_error=raises_on_error)
        else:
            error_message = f"File format not allowed: {in_doc.file}"
            error_item = ErrorItem(
                component_type=DoclingComponentType.USER_INPUT,
                module_name="",
                error_message=error_message,
                category=FailureCategory.POLICY,
            )
            conv_res = ConversionResult(
                input=in_doc, status=ConversionStatus.SKIPPED, errors=[error_item]
            )

        return conv_res

    def _execute_pipeline(
        self, in_doc: InputDocument, raises_on_error: bool
    ) -> ConversionResult:
        if in_doc.valid:
            pipeline_started = False
            try:
                pipeline = self._get_pipeline(in_doc.format)
                if pipeline is not None:
                    pipeline_started = True
                    conv_res = pipeline.execute(in_doc, raises_on_error=raises_on_error)
                else:
                    if raises_on_error:
                        raise ConversionError(
                            f"No pipeline could be initialized for {in_doc.file}."
                        )
                    else:
                        _log.warning(
                            "No pipeline could be initialized for %s.", in_doc.file
                        )
                        conv_res = ConversionResult(
                            input=in_doc,
                            status=ConversionStatus.FAILURE,
                        )
            finally:
                if not pipeline_started:
                    self._unload_input_document(in_doc)
        else:
            try:
                _log.warning("Input document %s is not valid.", in_doc.file)
                conv_res = ConversionResult(
                    input=in_doc,
                    status=ConversionStatus.FAILURE,
                    errors=build_invalid_input_errors(in_doc),
                )
            finally:
                self._unload_input_document(in_doc)

        return conv_res
